   143  void Uart::ReceiveTask(const uint8_t *aBuf, uint16_t aBufLength)
   144  {
   145      static const char sCommandPrompt[] = {'>', ' '};
   146
   147  #if OPENTHREAD_CONFIG_UART_CLI_RAW
   148      if (aBufLength > 0)
   149      {
   150          memcpy(mRxBuffer + mRxLength, aBuf, aBufLength);
   151          mRxLength += aBufLength;
   152      }
   153
   154      if (aBuf[aBufLength - 1] == '\r' || aBuf[aBufLength - 1] == '\n')
   155      {
   156          mRxBuffer[mRxLength] = '\0';
   157          ProcessCommand();
   158          Output(sCommandPrompt, sizeof(sCommandPrompt));
   159      }
   160  #else // OPENTHREAD_CONFIG_UART_CLI_RAW
   161      static const char sEraseString[] = {'\b', ' ', '\b'};
   162      static const char CRNL[]         = {'\r', '\n'};
   163      const uint8_t *   end;
   164
   165      end = aBuf + aBufLength;
   166
   167      for (; aBuf < end; aBuf++)
   168      {
   169          switch (*aBuf)
   170          {
   171          case '\r':
   172          case '\n':
   173              Output(CRNL, sizeof(CRNL));
   174
   175              if (mRxLength > 0)
   176              {
   177                  mRxBuffer[mRxLength] = '\0';
   178                  ProcessCommand();
   179              }
   180
   181              Output(sCommandPrompt, sizeof(sCommandPrompt));
   182
   183              break;
   184
   185  #if OPENTHREAD_POSIX
   186
   187          case 0x04: // ASCII for Ctrl-D
   188              exit(EXIT_SUCCESS);
   189              break;
   190  #endif
   191
   192          case '\b':
   193          case 127:
   194              if (mRxLength > 0)
   195              {
   196                  Output(sEraseString, sizeof(sEraseString));
   197                  mRxBuffer[--mRxLength] = '\0';
   198              }
   199
   200              break;
   201
   202          default:
   203              if (mRxLength < kRxBufferSize)
   204              {
   205                  Output(reinterpret_cast<const char *>(aBuf), 1);
   206                  mRxBuffer[mRxLength++] = static_cast<char>(*aBuf);
   207              }
   208
   209              break;
   210          }
   211      }
   212  #endif // OPENTHREAD_CONFIG_UART_CLI_RAW
   213  }
